package com.campus.trade.ai.dispute;
import com.campus.trade.ai.rule.ProductReviewRule; import com.fasterxml.jackson.databind.*; import org.springframework.ai.chat.client.ChatClient; import org.springframework.ai.openai.*; import org.springframework.beans.factory.ObjectProvider; import org.springframework.stereotype.Service; import java.util.*;
@Service public class DisputeAgentServiceModel { private final ObjectProvider<ChatClient.Builder> clients; private final DisputeAgentPromptService prompts; private final DisputeRuleService rules; private final DisputeAgentValidator validator; private final ObjectMapper json; private final DisputeAgentProperties props; public DisputeAgentServiceModel(ObjectProvider<ChatClient.Builder> c,DisputeAgentPromptService p,DisputeRuleService r,DisputeAgentValidator v,ObjectMapper j,DisputeAgentProperties x){clients=c;prompts=p;rules=r;validator=v;json=j;props=x;} public DisputeAgentResult analyze(Map<String,Object> snap){var b=clients.getIfAvailable();if(b==null)throw new IllegalStateException("AI ChatClient未配置");var rs=rules.currentRules();var allowed=rs.stream().map(x->x.ruleId()+"@"+x.version()).collect(java.util.stream.Collectors.toSet());String raw=b.build().prompt().options(OpenAiChatOptions.builder().model(props.getModel()).responseFormat(new org.springframework.ai.openai.api.ResponseFormat(org.springframework.ai.openai.api.ResponseFormat.Type.JSON_OBJECT,null)).build()).system(prompts.systemPrompt()).user(prompts.userMessage(snap,rules.currentVersion(),rs)).call().content();try{var out=json.copy().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,true).readValue(raw,DisputeAgentResult.class);validator.validate(out,allowed,snap);return out;}catch(Exception e){throw new DisputeAgentOutputInvalidException("AI_OUTPUT_INVALID",e);}}}
